"""What every case-file field is for. Read by engine/gen_docs.py, which writes
docs/generated/field-reference.md from it and from a scan of the code.

Each entry: JSON path -> (SEES, SECTION, NOTE)

  SEES     where the learner meets the value. One of the words in SEES_WORDS, or several
           joined by "+". "no" means the learner never sees it as text (it still acts).
           "never" means nothing in the engine or the build reads it: a note to reviewers.
  SECTION  the authoring-requirements section that governs it, or "" for a pure note.
  NOTE     one line. What it does, the trap if there is one.

Paths: "phases[]" is an element of the phases list. "content_keys.labs.<id>" is any study
id under labs. A path ending in ".*" covers every key below it. NOTE_KEYS lists key names
that are reviewer notes wherever they appear; they need no entry.

The generator checks each entry against the code: a path whose last key appears in no
engine, build or tool file is reported, and so is a field found in a case file with no
entry here. Keep this file true: a wrong line sends a builder to the wrong rule.
"""

SEES_WORDS = ["splash", "list", "history", "monitor", "figure", "sound", "chart", "nurse",
              "button", "debrief", "end", "no", "never"]

# Key names that are free text for the reviewing physician wherever they appear. Nothing
# reads them. Write them freely, and keep them out of anything the learner sees.
NOTE_KEYS = {
    "note", "notes", "authoring_note", "authoring_notes", "author_note", "author_rationale",
    "verify", "rationale", "schema_note", "schema_gap_note", "binding_note", "source",
    "provenance", "_note", "label_note", "vitals_note", "facts_note", "volunteers_note",
    "key_topics_note", "key_exams_note", "trap_actions_note", "intended_path_note",
    "attempt_history_note", "satisfied_by_note", "additional_diagnoses_note",
    "disposition_display_order_note", "out_of_scope_bank_note", "handover_authoring_note",
    "arrival_handover_authoring_note", "no_vital_effect_note", "prompt_removed_note",
    "turnaround_override_rationale", "unguarded_rationale", "terminal_opt_in_rationale",
    "variants_provenance", "follow_up_condition_note", "phases_note", "phase_notes",
    "flag_namespace_note", "prerequisite_semantics_note", "result_payload_contract",
    "tag_vocabulary", "authored_against", "migrations", "catalog_change_requests",
    "conformance_note", "teaching_frame", "changes_with_state", "result_shape", "prose",
    "engine_limitation_note",
}

